INSERT INTO `love_stories` (`id`, `title`, `location`, `description`, `thumbnail`, `status`, `display_order`, `order`, `created_at`, `updated_at`, `gallery`) VALUES
(1, 'Kajal & Akshay', 'Karad', 'Kajal and Akshay’s special day was full of happiness and beautiful traditions. During the ceremony, Akshay gently placed the mangalsutra around Kajal’s neck, and both of them smiled with pure joy. The bright colors, flowers, and blessings from family made the moment even more special. They looked at each other with love and excitement as they started their new journey together. Every ritual was filled with emotion and meaning. It was not just a wedding ceremony, but the beginning of a lifetime of togetherness, love, and countless beautiful memories.', 'uploads/stories/stories_1775442711_adc050f4.jpg', 'Active', 3, 2, '2026-02-24 12:40:16', '2026-05-11 07:31:21', 'uploads/stories/gallery/stories_gallery_1777310978_159060d8.jpg~%~uploads/stories/gallery/stories_gallery_1777310978_d3b56df0.jpg~%~uploads/stories/gallery/stories_gallery_1777310978_52547bea.jpg~%~uploads/stories/gallery/stories_gallery_1777310978_97ce2cfc.jpg~%~uploads/stories/gallery/stories_gallery_1777310978_4fecd380.jpg'),
(2, 'Gauri & Mayur', 'Karad', 'This lovely couple enjoyed every moment of their photoshoot. Sitting together near the small river, they laughed, talked, and had fun like no one was watching. The green trees and flowing water made the place calm and beautiful. They were very comfortable with each other, and their smiles were natural and real. We didn’t ask them to pose much — they just enjoyed being together. It felt less like a photoshoot and more like a happy day out. We captured their true happiness and special moments that they will always remember.', 'uploads/stories/stories_1775442789_ef6760fa.webp', 'Active', 1, 3, '2026-03-23 19:41:18', '2026-05-11 07:31:21', 'uploads/stories/gallery/stories_gallery_1777309610_51480e90.webp~%~uploads/stories/gallery/stories_gallery_1777309613_3e2d90bb.webp~%~uploads/stories/gallery/stories_gallery_1777309615_86d6f46a.webp~%~uploads/stories/gallery/stories_gallery_1777309617_c14e5dd2.webp~%~uploads/stories/gallery/stories_gallery_1777309622_dd5aee91.webp~%~uploads/stories/gallery/stories_gallery_1777309625_234decef.webp~%~uploads/stories/gallery/stories_gallery_1777309627_e0b7584c.webp'),
(3, 'Vijay & Shubhada', 'Karad', 'Vijay and Shubhada looked perfect together on their special day. Dressed in traditional attire, they stood side by side with pride and happiness. The bright sunlight and green surroundings made their moment even more beautiful. Vijay gently held Shubhada, and both of them looked excited to start their new life together. Their smiles were calm and full of love. It was a day filled with blessings, traditions, and joyful memories. This was not just a wedding photoshoot, but the beginning of a strong and beautiful journey as husband and wife.', 'uploads/stories/stories_1775442812_42ff8d13.webp', 'Active', 4, 3, '2026-03-23 19:41:18', '2026-05-11 07:31:21', 'uploads/stories/gallery/stories_gallery_1777310943_ed7fc0c6.jpg~%~uploads/stories/gallery/stories_gallery_1777310943_3eb3ee49.jpg~%~uploads/stories/gallery/stories_gallery_1777310944_12bab0d1.jpg'),
(6, 'Shaunak & Rupal', 'Mumbai', 'This couple’s photoshoot was full of love, warmth, and beautiful moments. During the golden sunset, they stood close, smiling and enjoying each other’s company. They were relaxed and natural, which made every photo look real and full of emotion. We had a great time capturing their connection as they laughed, talked, and shared quiet, special moments. The soft light and peaceful location made everything perfect. It didn’t feel like work for us or a shoot for them—it felt like a lovely evening spent together. They truly enjoyed every moment, and we loved capturing memories they will always cherish.', 'uploads/stories/stories_1777546897_757b9d4b.webp', 'Active', 2, 1, '2026-04-30 11:02:05', '2026-05-11 07:31:21', 'uploads/stories/gallery/stories_gallery_1777546899_3b369ed6.webp~%~uploads/stories/gallery/stories_gallery_1777546901_e631b2fe.webp~%~uploads/stories/gallery/stories_gallery_1777546903_247e2c2d.webp~%~uploads/stories/gallery/stories_gallery_1777546906_eae150dd.webp~%~uploads/stories/gallery/stories_gallery_1777546908_15d3e94c.webp~%~uploads/stories/gallery/stories_gallery_1777546909_f433e303.webp~%~uploads/stories/gallery/stories_gallery_1777546912_2b034146.webp~%~uploads/stories/gallery/stories_gallery_1777546913_28d8b0e9.webp~%~uploads/stories/gallery/stories_gallery_1777546916_ea449bc7.webp~%~uploads/stories/gallery/stories_gallery_1777546919_f01d7afd.webp~%~uploads/stories/gallery/stories_gallery_1777546922_5af4a99d.webp');

