INSERT INTO `testimonials` (`id`, `name`, `text`, `rating`, `status`, `created_at`, `display_order`, `updated_at`, `role`, `thumbnail`, `order`) VALUES
(14, 'Vijay & Shubhada', 'We had an amazing experience with The Patil Photography & Film\'s. They beautifully captured every important Maharashtrian wedding ritual, from Haldi to Saat Phere. The team was professional, friendly, and made us feel comfortable. Every photo reflects real emotions. Our family loved the album. Highly recommended for anyone looking for quality wedding photography.', 5, 'Active', '2026-04-07 17:50:51', 0, '2026-04-19 06:58:40', 'Karad', 'uploads/testimonials/testimonials_1775584251_39bd8fbf.jpg', 0),
(15, 'Kajal & Akshay', 'The Patil Photography & Film\'s did a fantastic job at our wedding. They captured every small detail and special moment beautifully. The team understood Maharashtrian rituals and emotions very well. Photos and videos came out beyond our expectations. We will always cherish these memories. Highly professional and creative team.', 5, 'Active', '2026-04-07 17:52:16', 0, '2026-04-07 17:52:16', ' Karad', 'uploads/testimonials/testimonials_1775584336_cf71b340.jpg', 1),
(16, 'Gauri & Mayur', 'Choosing The Patil Photography & Film\'s was the best decision for our wedding. They captured all our Maharashtrian traditions perfectly, including Sakharpuda and wedding vidhis. The photos are natural, elegant, and emotional. The team was very supportive and punctual. We are truly happy and thankful for these lifetime memories.', 5, 'Active', '2026-04-07 17:53:28', 0, '2026-04-07 17:53:28', 'Karad', 'uploads/testimonials/testimonials_1775584406_758e0890.webp', 2),
(17, 'Shaunak & Rupal', 'We had an amazing experience during our photoshoot. The photographer made us feel very comfortable from the beginning, which helped us be natural in front of the camera. The sunset location was perfect, and the way the moments were captured was truly beautiful. Every photo reflects real emotions, love, and happiness. We didn’t feel like we were posing; it felt like we were just enjoying our time together. The final pictures came out better than we expected. We are really happy with the results and will always cherish these memories. Highly recommended for anyone looking for natural and beautiful photography.', 5, 'Active', '2026-04-07 17:54:55', 0, '2026-04-07 17:54:55', 'Mumbai', 'uploads/testimonials/testimonials_1775584493_ef4de58e.webp', 3);

